<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $mode==='edit'?'Edit':'New' ?> Account · Puihaha Electric</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f3f6fb}.topbar{background:#102a56}.panel{border:0;border-radius:20px;box-shadow:0 8px 24px #102a5610}</style></head><body><nav class="navbar topbar navbar-dark"><div class="container"><a class="navbar-brand fw-bold" href="<?= base_url('dashboard') ?>">⚡ Puihaha Electric</a><span class="text-white small">Signed in as <?= esc($username) ?></span></div></nav><main class="container py-5" style="max-width:900px"><a href="<?= base_url('dashboard') ?>" class="text-decoration-none">← Back to accounts</a><div class="panel bg-white p-4 p-md-5 mt-3"><h1 class="fw-bold mb-1"><?= $mode==='edit'?'Edit customer account':'Add customer account' ?></h1><p class="text-secondary mb-4">Keep the service record accurate and up to date.</p><?php if ($message = session()->getFlashdata('message')): ?><div class="alert alert-danger"><?= esc($message) ?></div><?php endif; ?><form method="post" action="<?= $mode==='edit'?base_url('account/'.$account['id'].'/update'):base_url('account/create') ?>" class="row g-3"><div class="col-md-6"><label class="form-label">Account number</label><input class="form-control" name="account_number" value="<?= esc(old('account_number', $account['account_number']??'')) ?>" required></div><div class="col-md-6"><label class="form-label">Meter number</label><input class="form-control" name="meter_number" value="<?= esc(old('meter_number', $account['meter_number']??'')) ?>"></div><div class="col-md-6"><label class="form-label">Customer name</label><input class="form-control" name="customer_name" value="<?= esc(old('customer_name', $account['customer_name']??'')) ?>" required></div><div class="col-md-6"><label class="form-label">Email</label><input class="form-control" type="email" name="email" value="<?= esc(old('email', $account['email']??'')) ?>"></div><div class="col-md-6"><label class="form-label">Phone</label><input class="form-control" name="phone" value="<?= esc(old('phone', $account['phone']??'')) ?>"></div><div class="col-md-6"><label class="form-label">Connection type</label><select class="form-select" name="connection_type"><?php foreach(['residential','commercial','industrial'] as $value): ?><option value="<?= $value ?>" <?= old('connection_type', $account['connection_type']??'residential')===$value?'selected':'' ?>><?= ucfirst($value) ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach(['active','inactive','suspended'] as $value): ?><option value="<?= $value ?>" <?= old('status', $account['status']??'active')===$value?'selected':'' ?>><?= ucfirst($value) ?></option><?php endforeach; ?></select></div><div class="col-12"><label class="form-label">Service address</label><textarea class="form-control" name="address" rows="3" required><?= esc(old('address', $account['address']??'')) ?></textarea></div><div class="col-12 d-flex justify-content-end gap-2 mt-4"><a class="btn btn-light" href="<?= base_url('dashboard') ?>">Cancel</a><button class="btn btn-warning fw-bold"><?= $mode==='edit'?'Save changes':'Create account' ?></button></div></form></div></main></body></html>
